/bin/bash -lc "python - <<'PY'
import pysam
bam=pysam.AlignmentFile('variant.status.q1.bam','rb')
for col in bam.pileup('chrX',154398500-1,154398500, truncate=True, stepper='all', min_base_quality=0, max_depth=100000):
 print('col',col.reference_name,col.reference_pos+1,'n',col.nsegments,'pileups',len(col.pileups))
 for p in col.pileups:
  if p.is_del or p.is_refskip: print(p.alignment.query_name,'DEL/SKIP',p.is_del,p.is_refskip)
  else:
   q=p.query_position
   print(p.alignment.query_name,p.alignment.flag,p.alignment.reference_start+1,p.alignment.cigarstring,q,p.alignment.query_sequence[q],p.alignment.query_qualities[q])
PY"

